"""Build the seven-source compact detection copy and source fixture. Source build only; no DB/network."""
from pathlib import Path
import importlib.util
import json
import re

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location('compact_detection_parser', ROOT / 'script/schema/build_compact_schema.py')
parser = importlib.util.module_from_spec(spec)
spec.loader.exec_module(parser)
SOURCE = '__SOURCE_SCHEMA__'
OFFSET = '__SOURCE_DETECTION_OFFSET__'
OWNER, JOB, OBJECT, REVIEW, COMMAND, OUTBOX, WORKER = (
    'detection_creation_owner', 'detection_creation_job', 'detection_creation_object',
    'detection_creation_review', 'detection_execution_command', 'detection_dispatch_outbox', 'detection_worker_receipt')


def statements(file):
    return list(parser.split_top_level(parser.without_comments((ROOT / 'sql/mysql' / file).read_text(encoding='utf-8')), ';'))


def extract(items, table):
    return next(s for s in items if re.match(r'CREATE TABLE(?: IF NOT EXISTS)?\s+' + table + r'\s*\(', s)).replace('CREATE TABLE IF NOT EXISTS', 'CREATE TABLE', 1)


v42, v43, v50, v51 = (statements(f) for f in (
    'migration-V42-detection-execution.sql', 'migration-V43-detection-creation.sql',
    'migration-V50-detection-creation-transfer.sql', 'migration-V51-detection-creation-review.sql'))
job_sql = extract(v43, JOB).replace(' UNIQUE KEY uk_detection_creation_command',
    " revision BIGINT NOT NULL DEFAULT 0,\n bucket_name VARCHAR(128) NULL,\n source_prefix VARCHAR(512) COLLATE utf8mb4_bin NULL,\n manifest_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,\n UNIQUE KEY uk_detection_creation_command", 1)
ddl = {OWNER: extract(v43, OWNER), JOB: job_sql, OBJECT: extract(v50, OBJECT), REVIEW: extract(v51, REVIEW),
       COMMAND: extract(v42, COMMAND), OUTBOX: extract(v42, OUTBOX), WORKER: extract(v42, WORKER)}
tables = {name: parser.parse_table(sql, 'detection-runtime-source') for name, sql in ddl.items()}
if sum(len(table['columns']) for table in tables.values()) != 92:
    raise ValueError('Review every original detection-runtime column before changing the 92-column copy')
COLLATIONS = {name: 'utf8mb4_bin' for name in tables}
COLLATIONS[OBJECT] = '__SOURCE_DETECTION_OBJECT_COLLATION__'
COLLATIONS[REVIEW] = '__SOURCE_DETECTION_REVIEW_COLLATION__'


def q(value):
    return 'NULL' if value is None else "'" + str(value).replace('\\', '\\\\').replace("'", "''") + "'"


def payload(fields):
    return 'JSON_OBJECT(' + ','.join(q(key) + ',' + expression for key, expression in fields.items()) + ')'


def source(column):
    return 's.`' + column + '`'


def utc(column):
    return f"CONVERT_TZ({source(column)},'{OFFSET}','+00:00')"


def unquote(path):
    return "JSON_UNQUOTE(JSON_EXTRACT(t.payload_json,'$." + path + "'))"


def optional(path):
    return "CASE WHEN JSON_TYPE(JSON_EXTRACT(t.payload_json,'$." + path + "'))='NULL' THEN NULL ELSE " + unquote(path) + ' END'


def json_number(path):
    return 'CAST(' + optional(path) + ' AS DECIMAL(20,0))'


def time_valid(column, nullable):
    seconds = f"(IF(LEFT('{OFFSET}',1)='-',-1,1)*(CAST(SUBSTRING('{OFFSET}',2,2) AS SIGNED)*3600+CAST(SUBSTRING('{OFFSET}',5,2) AS SIGNED)*60))"
    valid = f"({utc(column)} IS NOT NULL AND TIMESTAMPDIFF(MICROSECOND,{utc(column)},{source(column)})={seconds}*1000000)"
    return f'({source(column)} IS NULL OR {valid})' if nullable else valid


lines = [
    '-- Generated by author_detection_runtime_copy.py; source artifact, NOT EXECUTED.',
    '-- Seven original tables, 92 columns. No source writes and no guessed actor for orphan uploads.',
    '-- Bind distinct admitted ECS schemas, actual OBJECT/REVIEW collations and evidenced fixed source UTC offset.',
    '-- The controller must stop source writers and backups must already exist; this script does not establish quiescence.',
    '-- Original cursors survive as legacy_key; target shared cursors are new identities.',
    '-- Worker/upload tokens are permanent non-reclaimable execution facts; NULL completion/update times stay unknown.',
    '-- Abort at the first SQL error, ROLLBACK on the same connection, never --force.',
    'SET NAMES utf8mb4;',
    'CREATE TEMPORARY TABLE compact_detection_guard(valid TINYINT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;',
]


def guard(expression):
    lines.append('INSERT INTO compact_detection_guard SELECT IF(COALESCE((' + expression + '),FALSE),1,0);')


guard(f"DATABASE() IS NOT NULL AND BINARY DATABASE()<>BINARY '{SOURCE}' AND @@FOREIGN_KEY_CHECKS=1 AND @@SESSION.sql_mode REGEXP '(^|,)(STRICT_TRANS_TABLES|STRICT_ALL_TABLES)(,|$)'")
guard("@compact_source_quiesced=1 AND @@SESSION.transaction_isolation='REPEATABLE-READ'")
guard(f"REGEXP_LIKE('{OFFSET}','^[+-][0-9]{{2}}:[0-9]{{2}}$','c') AND CONVERT_TZ('2026-01-01','{OFFSET}','+00:00') IS NOT NULL")
guard(f"(SELECT COUNT(DISTINCT privilege_type) FROM information_schema.schema_privileges WHERE BINARY table_schema=BINARY '{SOURCE}' AND privilege_type IN ('SELECT','TRIGGER') AND grantee=CONCAT(QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',1)),'@',QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',-1))))=2")
metadata=[]
for name, table in tables.items():
    collation=COLLATIONS[name]
    guard(f"(SELECT COUNT(*) FROM information_schema.tables WHERE BINARY table_schema=BINARY '{SOURCE}' AND BINARY table_name=BINARY '{name}' AND table_type='BASE TABLE' AND engine='InnoDB' AND BINARY table_collation=BINARY '{collation}')=1")
    for ordinal,(column,definition) in enumerate(table['columns'].items(),1):
        decl=definition['declaration']; kind=definition['type'].lower()
        explicit=re.search(r'\bCOLLATE\s+(\w+)',decl,re.I)
        coll=(explicit.group(1) if explicit else collation) if kind.startswith(('varchar','char','mediumtext','longtext','text')) else None
        nullable='NO' if column in table['primaryKey'] or 'NOT NULL' in decl.upper() else 'YES'
        extra='auto_increment' if 'AUTO_INCREMENT' in decl.upper() else ''
        found=re.search(r"\bDEFAULT\s+(CURRENT_TIMESTAMP(?:\(\d+\))?|'[^']*'|NULL|-?\d+)",decl,re.I)
        default=None
        if found:
            token=found.group(1)
            if token.upper().startswith('CURRENT_TIMESTAMP'):
                default=token.lower() if '(' in token else 'current_timestamp()';extra='default_generated'
            elif token.upper()!='NULL':default=token.strip("'")
        metadata.append((name,column,ordinal,kind,nullable,coll,default,extra))
names=','.join(map(q,tables))
lines += [
    'CREATE TEMPORARY TABLE compact_detection_columns(table_name VARCHAR(64),column_name VARCHAR(64),position_no INT,column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(table_name,column_name)) ENGINE=InnoDB;',
    'INSERT INTO compact_detection_columns VALUES\n'+',\n'.join('('+','.join(map(q,row))+')' for row in metadata)+';',
]
guard(f"NOT EXISTS(SELECT 1 FROM information_schema.columns a LEFT JOIN compact_detection_columns e ON BINARY e.table_name=BINARY a.table_name AND BINARY e.column_name=BINARY a.column_name WHERE BINARY a.table_schema=BINARY '{SOURCE}' AND a.table_name IN ({names}) AND e.column_name IS NULL)")
guard(f"NOT EXISTS(SELECT 1 FROM compact_detection_columns e LEFT JOIN information_schema.columns a ON BINARY a.table_schema=BINARY '{SOURCE}' AND BINARY a.table_name=BINARY e.table_name AND BINARY a.column_name=BINARY e.column_name WHERE a.column_name IS NULL OR NOT(a.ordinal_position<=>e.position_no) OR NOT(BINARY LOWER(a.column_type)<=>BINARY e.column_type) OR NOT(BINARY a.is_nullable<=>BINARY e.nullable) OR NOT(BINARY a.collation_name<=>BINARY e.collation_name) OR NOT(BINARY a.character_set_name<=>BINARY IF(e.collation_name IS NULL,NULL,'utf8mb4')) OR NOT(BINARY (CASE WHEN e.extra='default_generated' THEN REPLACE(LOWER(a.column_default),'()','') ELSE a.column_default END)<=>BINARY (CASE WHEN e.extra='default_generated' THEN REPLACE(LOWER(e.default_value),'()','') ELSE e.default_value END)) OR NOT(BINARY LOWER(a.extra)<=>BINARY e.extra) OR NOT(BINARY a.generation_expression<=>BINARY ''))")
guard(f"NOT EXISTS(SELECT 1 FROM information_schema.triggers WHERE BINARY event_object_schema=BINARY '{SOURCE}' AND event_object_table IN ({names}))")
guard(f"NOT EXISTS(SELECT 1 FROM information_schema.table_constraints WHERE BINARY table_schema=BINARY '{SOURCE}' AND table_name IN ({names}) AND constraint_type IN ('FOREIGN KEY','CHECK'))")
for name,table in tables.items():
    keys=[table['primaryKey'],*table['uniqueKeys']]
    guard(f"(SELECT COUNT(DISTINCT index_name) FROM information_schema.statistics WHERE BINARY table_schema=BINARY '{SOURCE}' AND BINARY table_name=BINARY '{name}' AND non_unique=0)={len(keys)}")
    for key in keys:
        columns=','.join(key)
        guard(f"(SELECT COUNT(*) FROM (SELECT GROUP_CONCAT(column_name ORDER BY seq_in_index SEPARATOR ',') AS shape FROM information_schema.statistics WHERE BINARY table_schema=BINARY '{SOURCE}' AND BINARY table_name=BINARY '{name}' AND non_unique=0 GROUP BY index_name) compact_key WHERE BINARY shape=BINARY '{columns}')=1")
    guard(f"NOT EXISTS(SELECT 1 FROM information_schema.statistics WHERE BINARY table_schema=BINARY '{SOURCE}' AND BINARY table_name=BINARY '{name}' AND non_unique=0 AND (sub_part IS NOT NULL OR expression IS NOT NULL OR index_type<>'BTREE' OR collation<>'A' OR is_visible<>'YES'))")
metadata_guards=[line for line in lines if line.startswith('INSERT INTO compact_detection_guard ')
                 and any('information_schema.'+table in line for table in ('tables','columns','statistics','triggers','table_constraints'))]
lines += [
    'CREATE TEMPORARY TABLE compact_detection_source_hwm(table_name VARCHAR(64) PRIMARY KEY,next_id DECIMAL(20,0) NULL) ENGINE=InnoDB;',
    f"INSERT INTO compact_detection_source_hwm SELECT table_name,auto_increment FROM information_schema.tables WHERE BINARY table_schema=BINARY '{SOURCE}' AND table_name IN ({names});",
    'CREATE TEMPORARY TABLE compact_detection_source_rows(table_name VARCHAR(64),key_sha256 CHAR(64),key_text LONGTEXT,row_sha256 CHAR(64),PRIMARY KEY(table_name,key_sha256)) ENGINE=InnoDB;',
    'START TRANSACTION WITH CONSISTENT SNAPSHOT;',
]
guard("(SELECT COUNT(*) FROM workflow_instance WHERE kind IN ('DETECTION_CREATION','DETECTION_TRANSFER','DETECTION_TRANSFER_REVIEW','DETECTION_COMMAND','DETECTION_DISPATCH','DETECTION_WORKER'))=0")
guard("(SELECT COUNT(*) FROM runtime_state WHERE namespace='DETECTION_CREATION_OWNER')=0")


def row_key(name):
    return 'CAST(JSON_ARRAY('+','.join(source(c) for c in tables[name]['primaryKey'])+') AS CHAR CHARACTER SET utf8mb4)'


def row_digest(name):
    # HEX each original SQL value: preserve NULL, exact JSON/TEXT and six-digit DATETIME bytes.
    values=[]
    for col,info in tables[name]['columns'].items():
        expression=source(col)
        if info['type'].upper().startswith('DATETIME'):
            expression=f"DATE_FORMAT({expression},'%Y-%m-%d %H:%i:%s.%f')"
        values.append('HEX(CAST('+expression+' AS BINARY))')
    return 'SHA2(CAST(JSON_ARRAY('+','.join(values)+') AS CHAR CHARACTER SET utf8mb4),256)'


for name,table in tables.items():
    for col,definition in table['columns'].items():
        if definition['type'].upper().startswith('DATETIME'):
            guard(f"NOT EXISTS(SELECT 1 FROM `{SOURCE}`.`{name}` s WHERE NOT COALESCE({time_valid(col,'NOT NULL' not in definition['declaration'].upper())},FALSE))")
    key=row_key(name)
    lines.append(f"INSERT INTO compact_detection_source_rows SELECT '{name}',SHA2({key},256),{key},{row_digest(name)} FROM `{SOURCE}`.`{name}` s;")


def workflow(name,kind,fields,projections,join=''):
    fields=dict(fields)
    if set(tables[name]['columns'])!=set(projections):
        raise ValueError('Incomplete original column mapping for '+name+': '+str(set(tables[name]['columns'])^set(projections)))
    fields.update(kind=q(kind),payload_version='1',legacy_source=q(name),legacy_key=source('id') if 'id' in tables[name]['columns'] else (source('command_id') if name==COMMAND else "CONCAT(s.task_id,CHAR(31),s.dispatch_id)"))
    lines.append('INSERT INTO workflow_instance('+','.join(fields)+')\nSELECT '+','.join(fields.values())+f' FROM `{SOURCE}`.`{name}` s'+join+(' ORDER BY s.id' if 'id' in tables[name]['columns'] else '')+';')
    guard(f"(SELECT COUNT(*) FROM workflow_instance WHERE kind='{kind}' AND legacy_source='{name}')=(SELECT COUNT(*) FROM `{SOURCE}`.`{name}`)")
    comparisons=[]
    for col,expression in projections.items():
        if tables[name]['columns'][col]['type'].upper().startswith('DATETIME'):
            comparisons.append(f'({expression}<=>{utc(col)})')
        else:comparisons.append(f'(BINARY {expression}<=>BINARY {source(col)})')
    guard(f"NOT EXISTS(SELECT 1 FROM `{SOURCE}`.`{name}` s LEFT JOIN workflow_instance t ON t.legacy_source='{name}' AND BINARY t.legacy_key=BINARY CAST({fields['legacy_key']} AS CHAR) WHERE t.id IS NULL OR NOT("+' AND '.join(comparisons)+'))')


lines.append("INSERT INTO runtime_state(namespace,owner_id,scope_key,revision,payload_version,payload_json,created_at,updated_at) "
             f"SELECT 'DETECTION_CREATION_OWNER',s.user_id,'',0,1,JSON_OBJECT('legacySource','detection_creation_owner'),NULL,NULL FROM `{SOURCE}`.`{OWNER}` s;")
guard(f"(SELECT COUNT(*) FROM runtime_state WHERE namespace='DETECTION_CREATION_OWNER')=(SELECT COUNT(*) FROM `{SOURCE}`.`{OWNER}`)")
guard(f"NOT EXISTS(SELECT 1 FROM `{SOURCE}`.`{OWNER}` s LEFT JOIN runtime_state t ON t.namespace='DETECTION_CREATION_OWNER' AND t.owner_id=s.user_id AND t.scope_key='' WHERE t.owner_id IS NULL OR t.created_at IS NOT NULL OR t.updated_at IS NOT NULL)")

job_payload=payload({k:source(c) for k,c in [('actorUsername','actor_username'),('actorRole','actor_role'),('proposalId','proposal_id'),('previewJson','preview_json'),('bucketName','bucket_name'),('sourcePrefix','source_prefix'),('manifestSha256','manifest_sha256')]})
job_projection={c:expression for c,expression in [
    ('id','CAST(t.legacy_key AS DECIMAL(20,0))'),('command_id','SUBSTRING(t.workflow_id,12)'),('actor_user_id','t.owner_user_id'),
    ('actor_username',optional('actorUsername')),('actor_role',optional('actorRole')),('request_id','t.request_id'),('proposal_id',optional('proposalId')),
    ('task_id','t.resource_id'),('dispatch_id','t.run_id'),('session_id','t.session_id'),('preview_json',optional('previewJson')),
    ('preview_sha256','t.request_sha256'),('status','t.status'),('owner_token','t.claim_token'),('lease_until','t.lease_expires_at'),
    ('reason_code','t.error_code'),('created_at','t.created_at'),('updated_at','t.updated_at'),('revision','t.revision'),
    ('bucket_name',optional('bucketName')),('source_prefix',optional('sourcePrefix')),('manifest_sha256',optional('manifestSha256'))]}
workflow(JOB,'DETECTION_CREATION',dict(workflow_id="CONCAT('det-create:',s.command_id)",idempotency_scope="CONCAT('OWNER:',s.actor_user_id)",request_id=source('request_id'),request_sha256=source('preview_sha256'),owner_user_id=source('actor_user_id'),actor_user_id=source('actor_user_id'),resource_type="'DETECTION_TASK'",resource_id=source('task_id'),run_id=source('dispatch_id'),session_id=source('session_id'),status=source('status'),revision=source('revision'),fence='IF(s.owner_token IS NULL,0,1)',claim_token=source('owner_token'),lease_expires_at=utc('lease_until'),error_code=source('reason_code'),payload_json=job_payload,created_at=utc('created_at'),updated_at=utc('updated_at'),finished_at='NULL'),job_projection)

transfer_payload=payload({k:source(c) for k,c in [('objectKey','object_key'),('contentSha256','content_sha256'),('byteLength','byte_length'),('contentType','content_type'),('etag','etag'),('objectVersion','object_version'),('ossRequestId','oss_request_id')]})
transfer_input=payload(dict(objectKey=source('object_key'),contentSha256=source('content_sha256'),byteLength=source('byte_length'),contentType=source('content_type'),etag='NULL',objectVersion='NULL',ossRequestId='NULL'))
# The request digest describes the immutable target only; historical SQL JSON formatting is not a Java digest.
transfer_projection=dict(id='CAST(t.legacy_key AS DECIMAL(20,0))',command_id='t.resource_id',image_index='t.resource_revision',file_id='t.run_id',object_key=optional('objectKey'),content_sha256=optional('contentSha256'),byte_length=json_number('byteLength'),content_type=optional('contentType'),state='t.status',upload_token='t.claim_token',etag=optional('etag'),object_version=optional('objectVersion'),oss_request_id=optional('ossRequestId'),updated_at='t.updated_at')
workflow(OBJECT,'DETECTION_TRANSFER',dict(workflow_id="CONCAT('det-upload:',LEFT(SHA2(CONCAT(s.command_id,':',s.file_id),256),48))",idempotency_scope="CONCAT('DETECTION_CREATION:',s.command_id)",request_id=source('file_id'),request_sha256='SHA2(CAST('+transfer_input+' AS CHAR CHARACTER SET utf8mb4),256)',owner_user_id='COALESCE(j.actor_user_id,0)',actor_user_id='j.actor_user_id',resource_type="'DETECTION_CREATION'",resource_id=source('command_id'),resource_revision=source('image_index'),run_id=source('file_id'),status=source('state'),fence='IF(s.upload_token IS NULL,0,1)',claim_token=source('upload_token'),payload_json=transfer_payload,created_at='NULL',updated_at=utc('updated_at'),finished_at='NULL'),transfer_projection,f' LEFT JOIN `{SOURCE}`.`{JOB}` j ON j.command_id=s.command_id')

review_payload=payload({k:source(c) for k,c in [('action','action'),('sourceCheckId','source_check_id'),('checkedCount','checked_count'),('verifiedCount','verified_count'),('evidenceJson','evidence_json'),('evidenceSha256','evidence_sha256'),('completedRevision','completed_revision')]})
review_projection=dict(id='CAST(t.legacy_key AS DECIMAL(20,0))',check_id='SUBSTRING(t.workflow_id,11)',command_id='t.resource_id',actor_user_id='t.owner_user_id',request_id='t.request_id',expected_revision='t.resource_revision',action=optional('action'),source_check_id=optional('sourceCheckId'),status='t.status',worker_token='t.claim_token',lease_until='t.lease_expires_at',checked_count=json_number('checkedCount'),verified_count=json_number('verifiedCount'),evidence_json=optional('evidenceJson'),evidence_sha256=optional('evidenceSha256'),completed_revision=json_number('completedRevision'),reason_code='t.error_code',created_at='t.created_at',updated_at='t.updated_at')
workflow(REVIEW,'DETECTION_TRANSFER_REVIEW',dict(workflow_id="CONCAT('det-check:',s.check_id)",idempotency_scope="CONCAT('OWNER:',s.actor_user_id)",request_id=source('request_id'),request_sha256="SHA2(CAST(JSON_OBJECT('command',s.command_id,'revision',s.expected_revision,'action',s.action,'sourceCheckId',s.source_check_id) AS CHAR CHARACTER SET utf8mb4),256)",owner_user_id=source('actor_user_id'),actor_user_id=source('actor_user_id'),resource_type="'DETECTION_CREATION'",resource_id=source('command_id'),resource_revision=source('expected_revision'),status=source('status'),fence='IF(s.worker_token IS NULL,0,1)',claim_token=source('worker_token'),lease_expires_at=utc('lease_until'),payload_json=review_payload,error_code=source('reason_code'),created_at=utc('created_at'),updated_at=utc('updated_at'),finished_at='NULL'),review_projection)

command_payload=payload(dict(commandId=source('command_id'),operation=source('command_type'),proposalId=source('proposal_id')))
command_projection=dict(command_id=optional('commandId'),actor_user_id='t.owner_user_id',request_id='t.request_id',command_type=optional('operation'),payload_sha256='t.request_sha256',proposal_id=optional('proposalId'),task_id='t.resource_id',dispatch_id='t.run_id',result_json='t.result_json',created_at='t.created_at')
workflow(COMMAND,'DETECTION_COMMAND',dict(workflow_id="CONCAT('det-cmd:',LEFT(SHA2(s.command_id,256),48))",idempotency_scope="CONCAT('OWNER:',s.actor_user_id)",request_id=source('request_id'),request_sha256=source('payload_sha256'),owner_user_id=source('actor_user_id'),actor_user_id=source('actor_user_id'),resource_type="'DETECTION_TASK'",resource_id=source('task_id'),run_id=source('dispatch_id'),status="'COMPLETED'",payload_json=command_payload,result_version='1',result_json='CAST(s.result_json AS CHAR CHARACTER SET utf8mb4)',result_sha256='SHA2(CAST(s.result_json AS CHAR CHARACTER SET utf8mb4),256)',created_at=utc('created_at'),updated_at='NULL',finished_at='NULL'),command_projection)

dispatch_payload=payload(dict(eventJson=source('payload_json'),actorRequestId=source('request_id')))
dispatch_projection=dict(id='CAST(t.legacy_key AS DECIMAL(20,0))',event_id='t.request_id',task_id='t.resource_id',dispatch_id='t.run_id',payload_json=optional('eventJson'),payload_sha256='t.request_sha256',actor_user_id='t.owner_user_id',request_id=optional('actorRequestId'),status='t.status',attempts='t.attempts',lease_token='t.claim_token',lease_until='t.lease_expires_at',next_attempt_at='t.next_attempt_at',last_error_code='t.error_code',created_at='t.created_at',updated_at='t.updated_at')
workflow(OUTBOX,'DETECTION_DISPATCH',dict(workflow_id="CONCAT('det-out:',LEFT(SHA2(s.event_id,256),48))",idempotency_scope="'DETECTION_DISPATCH'",request_id=source('event_id'),request_sha256=source('payload_sha256'),owner_user_id=source('actor_user_id'),actor_user_id=source('actor_user_id'),resource_type="'DETECTION_TASK'",resource_id=source('task_id'),run_id=source('dispatch_id'),status=source('status'),attempts=source('attempts'),fence='IF(s.lease_token IS NULL,0,GREATEST(1,s.attempts))',claim_token=source('lease_token'),lease_expires_at=utc('lease_until'),next_attempt_at=utc('next_attempt_at'),error_code=source('last_error_code'),payload_json=dispatch_payload,created_at=utc('created_at'),updated_at=utc('updated_at'),finished_at='NULL'),dispatch_projection)

guard(f"NOT EXISTS(SELECT 1 FROM `{SOURCE}`.`{WORKER}` s WHERE NOT REGEXP_LIKE(s.task_id,'^[A-Za-z0-9_-]{{1,128}}$','c') OR NOT REGEXP_LIKE(s.dispatch_id,'^[A-Za-z0-9_-]{{1,64}}$','c'))")
worker_identity="CONCAT('[',JSON_QUOTE(s.task_id),',',JSON_QUOTE(s.dispatch_id),']')"
worker_projection=dict(task_id='t.resource_id',dispatch_id='t.run_id',event_id='t.request_id',payload_sha256='t.request_sha256',owner_id='t.claim_token',status='t.status',result_json='t.result_json',result_sha256='t.result_sha256',started_at='t.created_at',updated_at='t.updated_at')
workflow(WORKER,'DETECTION_WORKER',dict(workflow_id="CONCAT('det-worker:',LEFT(SHA2("+worker_identity+",256),48))",idempotency_scope="'DETECTION_WORKER'",request_id=source('event_id'),request_sha256=source('payload_sha256'),owner_user_id='0',actor_user_id='NULL',resource_type="'DETECTION_TASK'",resource_id=source('task_id'),run_id=source('dispatch_id'),status=source('status'),fence='1',claim_token=source('owner_id'),payload_json="JSON_OBJECT('schemaVersion',1)",result_version='IF(s.result_json IS NULL,NULL,1)',result_json=source('result_json'),result_sha256=source('result_sha256'),created_at=utc('started_at'),updated_at=utc('updated_at'),finished_at='NULL'),worker_projection)

# Original row bodies, metadata and AUTO_INCREMENT high-water marks must remain unchanged.
for name in tables:
    key=row_key(name)
    guard(f"(SELECT COUNT(*) FROM compact_detection_source_rows WHERE table_name='{name}')=(SELECT COUNT(*) FROM `{SOURCE}`.`{name}`)")
    guard(f"NOT EXISTS(SELECT 1 FROM `{SOURCE}`.`{name}` s LEFT JOIN compact_detection_source_rows r ON r.table_name='{name}' AND r.key_sha256=SHA2({key},256) WHERE r.key_sha256 IS NULL OR BINARY r.key_text<>BINARY {key} OR r.row_sha256<>{row_digest(name)})")
guard(f"NOT EXISTS(SELECT 1 FROM compact_detection_source_hwm h LEFT JOIN information_schema.tables a ON BINARY a.table_schema=BINARY '{SOURCE}' AND BINARY a.table_name=BINARY h.table_name WHERE a.table_name IS NULL OR NOT(a.auto_increment<=>h.next_id))")
lines.extend(metadata_guards)
